export function RelatedPosts({
  heading = "{{heading}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  showExcerpt = {{showExcerpt}},
}) {
  const list = layout === "list";
  const posts = [
    { title: "Why smaller teams ship faster", excerpt: "Constraints force clarity, not the other way around." },
    { title: "A field guide to onboarding emails", excerpt: "Six templates we actually use, annotated." },
  ];
  return (
    <section style={{ font: "15px system-ui, sans-serif", color: "#241430", padding: 24 }}>
      <h2 style={{ margin: "0 0 16px", fontSize: 20, fontWeight: 700 }}>{heading}</h2>
      <div style={{ display: "grid", gap: 18, gridTemplateColumns: list ? "1fr" : "repeat(2, 1fr)" }}>
        {posts.map((post) => (
          <article key={post.title} style={{ display: list ? "flex" : "block", gap: 12, alignItems: "center" }}>
            <div role="img" aria-label="Thumbnail" style={{ borderRadius: 8, background: accent,
              width: list ? 72 : "auto", height: list ? 56 : 100, flexShrink: 0, marginBottom: list ? 0 : 10 }} />
            <div>
              <h3 style={{ margin: "0 0 4px", fontSize: 15, fontWeight: 700 }}>{post.title}</h3>
              {showExcerpt && <p style={{ margin: 0, fontSize: 13, color: "#241430aa" }}>{post.excerpt}</p>}
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}
